-- 設醮網站資料：資料表＋預設 8 篇文章＋初始主帳號 admin（第一次安裝匯入這個檔案；重複匯入不會產生重複文章，也不會把改過的密碼變回 admin）
-- 用法：mariadb -u tsio -p tsio -e "source install/setup.sql"

SET NAMES utf8mb4;

-- 文章
--  slug    ：網址用識別碼（預設文章是 ALUM-A00x，新文章是 a-{id}）
--  cover   ：上傳海報的檔名（放在 uploads/），可為空 → 前台用預設封面
--  content ：內文 HTML（後台編輯器產生，存檔前經過白名單過濾）
--  publish_at / unpublish_at ：上架、下架時間；留空 = 立即上架／不下架
--  created_by / updated_by    ：建立者、最後修改者（admin_users 的 id），預設文章是空的
CREATE TABLE IF NOT EXISTS articles (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  slug        VARCHAR(100) NOT NULL UNIQUE,
  title       VARCHAR(255) NOT NULL,
  description TEXT NOT NULL,
  date        VARCHAR(50)  NOT NULL DEFAULT '',
  location    VARCHAR(100) NOT NULL DEFAULT '',
  cover       VARCHAR(255) NULL,
  content     LONGTEXT NOT NULL,
  publish_at   DATETIME NULL,
  unpublish_at DATETIME NULL,
  created_by   INT UNSIGNED NULL,
  updated_by   INT UNSIGNED NULL,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 後台帳號
--  role                 ：owner 主帳號（老師，只有一個）／editor 副帳號（工讀生）
--  password_hash        ：密碼的雜湊（password_hash()），資料庫裡看不到原本的密碼
--  must_change_password ：1 = 下次登入要先改密碼（初始帳號、主帳號發的臨時密碼）
--  active               ：0 = 已停用，不能登入（文章上的作者紀錄還在）
--  session_version      ：改密碼、停用時加一，讓已登入的裝置登出
CREATE TABLE IF NOT EXISTS admin_users (
  id                   INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  username             VARCHAR(50)  NOT NULL UNIQUE,
  display_name         VARCHAR(50)  NOT NULL DEFAULT '',
  password_hash        VARCHAR(255) NOT NULL,
  role                 ENUM('owner', 'editor') NOT NULL DEFAULT 'editor',
  must_change_password TINYINT(1) NOT NULL DEFAULT 0,
  active               TINYINT(1) NOT NULL DEFAULT 1,
  session_version      INT UNSIGNED NOT NULL DEFAULT 1,
  last_login_at        DATETIME NULL,
  created_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 初始主帳號：帳號、密碼都是 admin，第一次登入要先改密碼。已經有就不覆蓋（重複匯入不會把密碼變回 admin）
INSERT IGNORE INTO admin_users (id, username, display_name, password_hash, role, must_change_password)
  VALUES (1, 'admin', '主帳號', '$2y$10$YwKv6UKmrueHgeTATJpo4O5P0YlCRqRCcuYTr.6OENdonWXcSUqQ2', 'owner', 1);

-- 後台登入失敗紀錄（防暴力猜密碼）
CREATE TABLE IF NOT EXISTS login_attempts (
  ip           VARCHAR(45) NOT NULL PRIMARY KEY,
  fail_count   INT UNSIGNED NOT NULL DEFAULT 0,
  first_failed DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO articles (slug, title, description, date, location, cover, content, created_at) VALUES ('ALUM-A001', '【三今設計】從產品設計到斜槓創業：連子沂的設計實踐之路', '本文專訪本校畢業的資深 UX 設計師 OOO，分享他在 Google 擔任產品設計師期間，如何平衡創新與使用者需求的挑戰與心得。', '04 08 2025', '校友特稿', NULL, '<h3>專訪｜連子沂：以永續理念打造兼具功能與價值的產品設計</h3>\n<p>連子沂，目前擔任三今設計負責人，帶領團隊專注於產品外觀設計。除了核心的外觀設計服務，三今設計還提供產品建模、概念設計、產品動畫與模型製作等全方位設計服務，為客戶提供從概念到實現的一站式解決方案。對連子沂而言，設計不僅是解決功能需求的工具，更是一種思考人、環境與產品三者關係的方式。</p>\n<p>他表示：「我們希望產品不只是功能導向，也不只是滿足業主需求，而是能同時關注環境議題，將永續設計理念融入其中。」</p>\n<p>這份理念源於他的大學時期。從最初的專題發想就以永續為核心，連子沂在接案過程中，也常說服業主將 永續發展目標（SDGs） 的元素納入設計。他認為，真正好的產品設計，應該在滿足使用者需求的同時，也兼顧社會與環境的價值。在她的帶領下，三今設計不僅完成了多項創新的產品設計專案，也將永續理念落實於每一個設計決策，持續拓展產品與環境、社會之間的關聯。</p>\n<h3>一次填志願的轉向，開啟工業設計之路</h3>\n<p>子沂在高中填志願之前，一直打算念建築，因為家裡背景與建築相關。不過在填志願時，第一次接觸到工業設計，發現這個領域比建築更廣，也有更多發揮的空間。這份發現讓他產生興趣，並想深入了解工業設計的工作內容、設計思維與實務應用。</p>\n<p>在學習過程中，連子沂認為對他幫助最大的是 獨立思考與執行力。在概念發想階段，老師主要扮演引導角色，真正要將想法建立、清楚表達並說服他人，完全依靠自己。這要求他先釐清議題、界定問題，再以有邏輯的方式呈現觀點。</p>\n<p>執行力也直接體現在成果的呈現上。連子沂表示，設計不能僅停留在文字或口頭描述，而必須透過模型、視覺或動畫將概念具體化，並思考哪種呈現最能傳達重點。從草圖到打樣，再到最後展示，每一步都考驗執行與落地能力。</p>\n<h3>從成就感到現實磨練：一次難忘的跨國合作經驗</h3>\n<p>談到過去的接案經驗，他坦言幾乎每一個專案都能帶來成就感，他為了累積實務經驗，幾乎不設限地承接各類設計服務。「有案就接」是當時的常態；隨著案源逐漸穩定，才開始有意識地收斂方向，將重心聚焦在工業產品開發與產品設計上。</p>\n<p>對他而言，產品設計不只是工作，而是一件真心喜歡的事，因此每當專案完成，並獲得客戶高度回饋時，那種成就感格外強烈。其中，最令他印象深刻的，是一項為科技新創公司（日本分公司／體制側）所進行的設計專案。該案為一款應用於 SPC（金屬電路板）的產品進行射出外殼設計，產品機構本身並不複雜，但專案流程卻非常漫長。</p>\n<p>這次經驗也讓他對「專案成本」有了更深刻的理解。他指出，設計成本不僅僅是設計本身，還包含反覆溝通、決策等待的時間成本，甚至是專案「休眠後重啟」所需投入的復整工時。</p>\n<p>「資料雖然調得出來，但當時的思考脈絡與判斷邏輯，必須重新整理與醞釀，這讓其實相當折騰。」他表示，這些隱性成本，都應該在專案一開始就納入評估。</p>\n<p>他分享，前述幾個專案多半屬自與其他品牌的合作創作，而這對經營設計工作室而言至關重要。他認為，設計師一定要為自己保留一段「創作時間」，不為特定客戶需求所限，主動吸收美感、持續打磨美感與專業深度，並產出能對外展示的作品。</p>\n<h3>從設計服務走向產品品牌：三今設計的下一步</h3>\n<p>在談及對「成功」的定義時，他並不以事業規模作為衡量標準。對連子沂而言，真正重要的是能否在工作與生活之間取得平衡，持續從事自己不計酬、甚至能長期投入的事情。他也希望以相對從容的節奏經營事業，保持對工作的熱忱與穩定心態，也因此選擇不讓自己陷入長期消耗，違背初衷的工作模式。</p>\n<p>展望未來三年的品牌與事業發展，他指出，過去以設計服務為主的階段已逐漸告一段落，目前僅維持與既有客戶的合作，並將更多時間與心力投入自有品牌的設計師作品與產品開發，朝「設計師品牌」方向前進。</p>\n<p>在他的觀察中，台灣以設計接案為主要收入來源，並非一種長期健康的商業模式，更適合作為打磨技術、累積經驗與資金的過渡階段；而真正具備長期發展潛力的，仍是能夠累積價值的產品。隨著品牌策略的調整，未來三今設計也將把重心放在產品端，逐步建立更具持續性的事業結構。</p>\n<p>同時，由於經營咖啡廳這項副業，他也必須在設計、產品與生活之間重新分配時間。對他而言，這樣的取捨並非分心，而是為了讓工作與生活都能以更健康、可長可久的方式前進。</p>\n<h3>致想創業的學生與年輕設計師——設定目標、果斷行動</h3>\n<p>他建議創業首先要設定明確目標，清楚知道自己想達成什麼；接著是執行力，目標一旦確定就應立即付諸行動。其次，創業過程中要學會邊做邊調整，因為理想與市場需求往往存在差距，需要靈活應對、與市場節奏同步。</p>\n<p>最後，他強調設定停損點的重要性，提前規劃在遭遇多少挫折或虧損時應果斷停止或調整商業模式，必要時甚至收掉公司，以便為下一步做更理性的判斷。</p>', '2025-01-01 00:00:00')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), date = VALUES(date), location = VALUES(location), cover = VALUES(cover), content = VALUES(content), created_at = VALUES(created_at);
INSERT INTO articles (slug, title, description, date, location, cover, content, created_at) VALUES ('ALUM-A002', '【合聿設計】從畫圖的人，到帶團隊的人　巫偉哲的設計思維——工作室專訪', '本文專訪合聿設計負責人巫偉哲，分享他從設計師到帶領團隊的歷程，以及他對設計思維與工作室經營的獨到見解。', '04 08 2025', '校友特稿', NULL, '<h3>專訪｜巫偉哲：以整合為核心，從品牌到空間的一體化設計思維</h3>\n<p>成立於 2013 年的合聿設計工作室，由兩位具美英設計背景的創辦人共同創立。工作室以「空間設計」與「品牌規劃」為雙核心服務，致力於提供從品牌創立、策略定位到商業空間實踐的一體化整合設計。團隊成員分工明確卻高度協作，其中一位創辦人畢業於長庚大學，專注於室內與商業空間設計；另一位則負責品牌策略與整體品牌規劃。這樣跨領域的合作模式，使設計在品牌理念與空間細節之間得以完整銜接，避免傳統設計流程中常見的落差。</p>\n<p>合聿服務範圍涵蓋餐飲、醫療產業及企業轉型品牌。面對不同產業需求，團隊從品牌核心出發，結合使用者體驗與實際營運考量，將抽象的品牌概念轉化為可被感知、被使用的實體空間。相較於單一領域的設計服務，合聿更重視整體一致性，確保品牌形象在視覺、空間與體驗層面皆能完整呈現。</p>\n<p>「聿」一字源自甲骨文，象徵人以手握筆、開始創作的動作，也代表合聿對設計本質的理解——設計是一場由客戶與設計師共同參與、相互激發的過程。透過密切溝通與協作，合聿期望每件作品都能回應最初的需求，並保留那份最真實的感動。</p>\n<h3>從探索方向到設計養成—工設帶來的長期影響</h3>\n<p>回顧學習歷程，巫偉哲表示，選擇工業設計並非一開始就有明確目標，而是在探索中逐漸找到方向。進入大學前，他對未來仍感迷惘，直到接觸工業設計，才發現這個領域與自身興趣高度契合。工業設計橫跨產品設計、UI／UX 與視覺溝通，讓他理解設計需整合思考，一件產品不僅是造型與功能，更要被理解、推廣並接受市場，這也成為他投入工業設計的重要原因。</p>\n<p>畢業後雖未從事產品設計，但學期間建立的材料運用、立體結構、空間感與使用者研究，仍影響他後續的品牌與室內設計工作。尤其在品牌設計中，他常回到工業設計強調的前期研究，明確界定目標族群，讓設計回應需求並被市場接受。</p>\n<p>談到大學時期最深刻的影響，他指出，那是一個必須「親手完成所有事情」的年代。概念發想、模型製作到成果發表，拍照、排版與展示都需自己完成，3D 列印尚未普及，CNC 僅用於特殊情況，其餘多靠手工。正是在這樣高強度的訓練中，他培養了對細節的敏感度與負責態度，也為日後品牌、空間與商業整合奠定基礎，成為創業的重要養分。</p>\n<h3>土法煉鋼的年代：手作磨出的設計底子</h3>\n<p>他回憶起大學時期，與現在最大的不同是工具與資源的落差。如今AI與各種設計軟體讓製作流程更快速有效，但在當年，每一個專案都必須靠雙手完成。從發想、打樣到最終呈現，所有細節都得親自處理。</p>\n<p>沒有3D列印機，大多數模型必須DIY完成；CNC只用於特別困難的結構。發表時的作品照片、排版設計，也都要自己拍攝與編排。</p>\n<p>巫偉哲表示:「那是一個真的在練基本功的年代。」這樣的土法煉鋼，不只訓練技術，也培養了解決問題的能力。</p>\n<h3>創業的三個階段：從接案者，到經營者，再到領導者</h3>\n<p>談及創業歷程，巫偉哲將其劃分為三個階段，每一階段的挑戰都截然不同。自 2013 年創立公司至今，他形容這段過程是不斷轉換角色與思維的學習。</p>\n<p>創業初期，最大的課題是「如何活下來」。他與夥伴從零開始接案，沒有員工，所有案子都必須親自承接與執行，無論類型是否理想，都必須嘗試。當時最辛苦的不是畫圖，而是學習如何報價、提案，以及在有限資源下兼顧設計品質與客戶需求。</p>\n<p>三、四年後，隨著員工加入，挑戰轉向團隊管理。過去所有設計與決策都掌握在自己手中，但組織成形後，他必須思考如何分工、建立流程與訂定規則，讓團隊能順利運作。對他而言，這是一段心態轉換的過程，從「自己把事情做好」，到「讓團隊把事情做好」。</p>\n<p>十年後，他的角色再次轉變，已不再直接執行設計，而是帶領設計師完成專案，確保成果品質符合期待，也能被客戶接受。經營壓力也更具體：公司規模擴大，如何在預算、品質與組織永續間取得平衡，成為設計之外的重要課題。他坦言，這三個階段各有挑戰，每一次轉換都需重新學習。即使到了現在，他仍需調整經營方式，思考制度與福利，而不只是持續接案與產出設計。更是建立一個能讓團隊長期運作、共同成長的環境。</p>\n<h3>從挫折到信任：創業與客戶溝通之道</h3>\n<p>談及創業過程中是否曾想過放棄，巫偉哲坦言，其實並沒有。身邊有許多創業朋友，以及在大型設計公司擔任高職位的人，他觀察到，即便他們地位再高，仍需受制於老闆的方向與制度；相較之下，他可以自主決定想做的事情，因此從未想過放棄。</p>\n<p>當然創業過程中仍遇到不少挫折，例如如何調整經營策略，或是作品定位問題。初期什麼都接時，很難建立清晰的作品風格；如今，他已能篩選客戶與服務，專注於自己擅長且有興趣的品牌設計領域。</p>\n<p>對於最令人印象深刻的合作經驗，他最難忘的是願意信任團隊的業主。例如曾操作一個牙醫品牌，業主完全不修改設計稿，使團隊能呈現接近原先想像的整體質感。對巫偉哲而言，這類業主特別令人印象深刻。</p>\n<p>而面對客戶意見分歧，他強調以專業與經驗溝通。他會透過過往成功與失敗案例，解釋設計決策的原因，讓客戶理解建議背後的邏輯。</p>\n<p>「100個案子裡一定有20個不成功。」</p>\n<p>他認為，理想與市場並無絕對平衡，重點是找到最合適的方法。只要業主目標明確，設計就是協助達成；若方向不易成功，他則會以失敗案例說明，讓溝通更有效。</p>\n<h3>致想創業的學生與年輕設計師—熱忱是創業的核心動力</h3>\n<p>巫偉哲認為，創業最重要的是保持熱情。他指出身邊能持續走下去的創業朋友都有共同特質—對正在做的事充滿熱情與執著。當找到自己喜歡且能享受其中的工作時，這份熱忱便會成為持續前行的動力。因此他強調，創業者一定要保有對事物的熱愛，才能在挑戰與困難中堅持下去。</p>', '2025-01-01 00:00:01')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), date = VALUES(date), location = VALUES(location), cover = VALUES(cover), content = VALUES(content), created_at = VALUES(created_at);
INSERT INTO articles (slug, title, description, date, location, cover, content, created_at) VALUES ('ALUM-A003', '【Tzaba】從家中車庫到手作皮革工作室　蘭亞青的創意生活——工作室專訪', '本文專訪 Tzaba 皮革工作室創辦人蘭亞青，分享她從家中車庫起步到經營手作皮革工作室的創意生活歷程。', '04 08 2025', '校友特稿', NULL, '<h3>專訪｜蘭亞青：以手作連結在地文化—皮革職人之路</h3>\n<p>位於基隆義一路、快接中正路口的「Tzaba喳吧」，是一家融合皮革創作、體驗課程與展示空間的手作工作室。店名「Tzaba喳吧」意寓歡樂的交談聲，象徵店內創作與互動的活力。</p>\n<p>工作室主人蘭亞青，擁有工業設計背景，不僅親自設計與製作皮革作品，也參與空間規劃與家具設計，將自家車庫改造為兼具創作與教學功能的工作室。在這裡，她提供客製化接單服務、手作教學課程，以及與團體的合作活動，教學對象從學生、老師到小朋友皆有。</p>\n<p>蘭亞青特別注重將在地文化融入創作中。她會向周邊本土漁民購買魚鉤、漁網等素材，將海洋元素與皮革結合，形成獨具特色的手作作品。對她而言，核心價值在於「回家工作」，透過創作推廣在地文化風情，將生活、創作與社區連結起來。</p>\n<p>工作室環境明亮舒適，除了皮革作品，也陳列老物件，搭配自然光、燈光與音樂，營造和諧氛圍。店內還養了一隻烏龜，悠然自得地在角落活動，像是小小的守護者，也呼應了工作室的命名理念——在小空間裡，創作與交流同步發生。</p>\n<h3>從模型到皮革：工業設計如何塑造我的創業視野</h3>\n<p>蘭亞青回顧大學選擇工業設計的初衷，坦言並非一開始就為創業做準備，而是透過課程逐步發現自己的興趣所在。手作課程如模型、金工與雕塑，雖然耗時繁複，甚至令她覺得討厭，但對後續開創皮革事業幫助極大——工業設計提供了一個良好的入門基礎，也讓她覺得皮革像是可塑性極高的材料。</p>\n<p>大學期間，幾位老師對她影響深遠。艾倫諾老師的嚴格要求，讓她既愛又恨；而陳文誌老師在畢業製作時提供的自由發揮空間，讓她更堅定自己對作品的想法與追求。這些經驗塑造了她的設計判斷，也培養了勇於嘗試與創新的態度。</p>\n<p>工業設計的訓練，除了手作能力外，更重要的是多角度思考問題的能力。蘭亞青分享，她會花費大量心力研究如何善用邊角料，讓客人以合理價格購買或在手作課程中使用，同時不必過度擔心成本。這種以不同視角解決問題的能力，成為她後續創業的重要基礎。</p>\n<h3>從好奇到實踐：創業，是一場自然而然的旅程與時間挑戰</h3>\n<p>蘭亞青表示，創業對她而言是一個自然而然的過程，並非源自某個驚天動地的契機。她曾在台北的公司工作，以環保素材製作生活器具，但因人際壓力選擇辭職。回到基隆後，先在咖啡廳打工，給自己時間接觸花藝與皮革，最終發現皮革更具實用性，便開始踏上創業之路。</p>\n<p>創業初期最大的挑戰是客製化商品的製作時程。由於多為第一次嘗試，製作過程耗時，即便短夾等常見商品能稍快完成，其他客製化產品仍難免花費大量時間。面對緊迫的交期，她經常熬夜完成訂單，有時甚至因實驗性產品難以如期完成而感到挫折，這也是創業過程中最容易產生想放棄的時刻。</p>\n<h3>從小訂單到穩定客群：手作創業的成就與學習</h3>\n<p>對蘭亞青而言，每一次合作經驗都令人印象深刻，尤其是看到成品完成時的成就感。家中有姪子的陪伴，也讓她在手作課程中累積更多經驗與耐心。她的創業之路從親朋好友及附近鄰居的委託訂單開始，逐步建立聲譽，慢慢形成穩定的客群與回頭客。</p>\n<p>面對客戶意見分歧，蘭亞青強調尊重客人的想法，同時提供專業建議，嘗試說服客戶，但最終仍依客人需求進行客製化設計——畢竟，客製化訂單付費的是客戶。對她而言，創業最大的改變並非生活方式或理念，而是能持續做自己喜歡的事，並堅守初心。</p>\n<h3>小而精緻，自成風格：三年品牌願景</h3>\n<p>蘭亞青表示，未來三年她希望維持工作室的小而精緻經營，不追求規模擴張。她希望減少對社群媒體與廣告的依賴，讓作品本身與口碑自然成為宣傳的力量。透過分享手作皮革的創作成果，她期望吸引真正熱愛皮革、欣賞手作精神的客群，逐步建立一個專屬於手作文化的穩定社群。</p>\n<h3>勇敢從零開始——致年輕創業者的建議</h3>\n<p>對於有志創業的學生或年輕設計師，蘭亞青建議「趁早行動」。她認為，在尚未受制於公司制度或現實壓力之前，正是嘗試創業、累積經驗的最佳時機。這段期間可以勇於摸索、試錯，不被金錢或現實顧慮束縛，培養面對挑戰的膽識與自信，避免因過多考量而退縮不前。</p>', '2025-01-01 00:00:02')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), date = VALUES(date), location = VALUES(location), cover = VALUES(cover), content = VALUES(content), created_at = VALUES(created_at);
INSERT INTO articles (slug, title, description, date, location, cover, content, created_at) VALUES ('ALUM-A004', '【同心設計】從紙上到城市 郭竑逸的設計轉身——工作室專訪', '本文專訪同心設計工作室成員郭竑逸，分享他從紙上設計擴展到城市空間設計的心路歷程。', '04 08 2025', '校友特稿', NULL, '<h3>專訪｜郭竑逸：從平面創作到空間雕塑，用設計連結生活、理念與城市痕跡</h3>\n<p>郭竑逸的設計旅程，最初是在平面的世界展開。剛出道時，他接觸的多是平面設計案，為品牌製作海報、視覺識別等作品。然而，隨著時間推移，他開始將重心逐步轉向室內設計。原因很單純：市場上的室內案子多、量大且穩定。在台北這座老房子與新屋交錯的城市，即使是新房，也常需要冷氣裝修、磁磚更新或空間重新規劃。對郭竑逸而言，室內設計不只是工作，它是一種持續創作的方式，讓他在每一天都能感受到設計的呼吸，並將平面設計累積的視覺語彙轉化為立體空間的表現力。</p>\n<p>同心設計團隊專注於室內與品牌設計，由設計師親手操刀，擅長英倫、美式、簡約、現代及日式風格，對材料質感與光影的運用尤為講究。他們執著於綠色、安全、人本與自然，持續追求卓越，力求打造每一件令人驕傲的作品。對郭竑逸而言，設計是一種生活方式，也是自我表達的延續——從平面的細節到空間的光影，他的設計始終帶有故事性與溫度。</p>\n<h3>工業設計的初心及設計訓練的寶藏</h3>\n<p>回想當初為何選擇工業設計，郭竑逸坦言，填志願時其實一無所知，只被「每次作品都能不一樣」吸引。高中時，升學壓力讓他質疑念書的意義，休學一年，他看展、看電影、感受世界的多樣性，最終選擇設計——一個不必整天盯著文字，卻能持續創造、自由探索的世界。</p>\n<p>對他而言，設計不只是職業，而是一種生活方式，也是一種自我探索的途徑。</p>\n<p>談到工設系的學習，他認為最有價值的是「基本設計」課程，雖然當時枯燥，卻幫助他建立分析與審美邏輯。而「攝影課」則教會他光線與構圖的重要性，使作品呈現時更生動、有生命力。他常提醒學生：「設計不只是作品本身，怎麼呈現、怎麼拍，也是設計的一部分。」在他看來，好的作品如果拍攝呈現不佳，也會讓整體美感大打折扣。</p>\n<h3>創業：從現實出發的勇氣</h3>\n<p>談到創業，郭竑逸坦言，最初的動機並非浪漫理想，而是現實需求。剛畢業時，他的薪水大約三萬多到四萬，根本無法支撐生活。憑藉平面設計經驗，他知道市場願意為設計付費，因此決定靠自己闖一片天，而不依賴家人的支援。</p>\n<p>此外，他並不適應辦公室生活。曾在一家設計公司實習兩個月，環境與同事都很好，但實習結束後他發現：「我要轉行。」被動執行別人的想法，與自己創作的快樂完全不同。於是，他選擇自由接案，用摩托車穿梭城市，用每一個案子支撐生活。辛苦與自由並存，但他感受到前所未有的掌控感，這也是創業最初的動力。</p>\n<h3>生存與成長的考驗留下的痕跡</h3>\n<p>創業初期，生存是最現實的挑戰。郭竑逸什麼案子都接，從修廁所、修漏水到小型設計案，思考單純：先讓公司活下來。那段日子，他的壓力比高三考試還大，不只是怕失敗，更怕違約或賠錢。然而，也正是這樣的壓力逼迫他去學很多新技能，磨練出面對挑戰的勇氣，也讓他在實務中快速成長。</p>\n<p>隨著經驗累積與案源增加，他逐漸學會挑案子，思考哪些案子對作品或公司真正有意義。從「接一切能接的案子」到「精選能彰顯風格與理念的案子」，這段歷程成為他創業過程中最重要的一段學習曲線。</p>\n<p>在所有作品中，郭竑逸印象最深刻的是一間酒吧空間。商業空間的魅力在於，它不僅是設計，更是城市的一部分。路人可以看見、感受他的設計，作品不再只是私人的存在，而成為品牌理念的延伸。相較住宅案，商業空間給了他更多自由，能完整呈現自己的風格與理念，也因此每一次完成案子，都能帶來強烈的成就感與滿足。</p>\n<h3>理想與現實的平衡到未來三年期許</h3>\n<p>一開始創業，他幾乎沒有理想，目標只有活下去。隨著公司穩定後，他開始挑選能表現風格的案子，將美感與功能巧妙融合。每個空間都有操作邏輯與使用需求，而當功能與美感完美結合時，那種成就感與滿足，是平面設計無法給予的。室內設計讓他感受到，設計不只是視覺的呈現，更是一種生活經驗的雕塑。</p>\n<p>展望未來，他希望同心設計能持續穩定成長，承接更多具挑戰性的商業空間案，也希望自己的作品被更多人看見。對郭竑逸而言，設計不只是「好看」，更要有故事、有想法。他希望在現實與理想之間，讓自己的設計生涯如光影般延伸，留下持久而深刻的痕跡。</p>\n<h3>給準備起步的人：在現實中長出勇氣的創業建議</h3>\n<p>郭竑逸認為，創業並不是浪漫的選項，而是一條高度貼近現實的道路。他提醒有意創業的學弟妹，必須先誠實面對一件事——創業真的很累，也不一定適合每一個人。它考驗的不只是設計能力，更是抗壓性、溝通力與長時間獨立面對問題的心理狀態。</p>\n<p>如果確定想走這條路，他給出的第一個建議是：不要怕問人、不要愛面子，也不要害怕被拒絕。許多彎路其實都有人走過，願意開口請教、向前輩學習，反而能大幅縮短摸索時間。無論是流程、報價、合約或實務細節，懂方法、懂系統，遠比單靠熱情硬撐來得重要。</p>\n<p>他也強調，創業初期不需要逞強。適時補課、進修，甚至承認自己不懂，都是專業成長的一部分。真正能走得久的人，往往不是最逞強的，而是最能調整心態、承受挫折的人。對郭竑逸而言，創業的關鍵從來不只是「撐下去」，而是在一次次現實考驗中，慢慢建立屬於自己的節奏與信心。</p>', '2025-01-01 00:00:03')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), date = VALUES(date), location = VALUES(location), cover = VALUES(cover), content = VALUES(content), created_at = VALUES(created_at);
INSERT INTO articles (slug, title, description, date, location, cover, content, created_at) VALUES ('ALUM-A005', '【小光點畫家】在微光中重生的力量 鄭佩淳:生命鬥士創業故事——桃園專訪', '本文專訪小光點畫家鄭佩淳，分享她以畫筆與生命對話，從困境中誕生創作能量，走出屬於自己的創作與創業道路。', '04 08 2025', '校友特稿', NULL, '<h3>專訪｜鄭佩淳：小光點畫家的溫柔力量</h3>\n<p>在桃園的一隅，有一位用畫筆與生命對話的創作者——小光點畫家鄭佩淳。她的人生並非一路順遂，卻在跌跌撞撞之中，走出屬於自己的創作與創業道路。對她而言，創作不是為了市場，而是一種自我療癒與重生的方式；創業，也不是宏大的藍圖，而是一步步為自己爭取活下去與發光的機會。</p>\n<h3>從困境中誕生的創作能量</h3>\n<p>畢業後，她曾像多數設計系學生一樣接案、累積作品、規劃未來，甚至成立工作室，嘗試讓創作更制度化、專業化。然而，身體狀況的變化讓她不得不按下暫停鍵。那段時間，她面對的不只是健康問題，還有對未來的不確定與自我價值的質疑。</p>\n<p>當生活的節奏慢下來，她才發現，自己其實從未真正停下創作的渴望。畫畫成為一種出口。不是為了展覽，也不是為了販售，而是單純地把情緒放進畫面，把那些說不出口的焦慮與不安，一筆一筆釋放出來。</p>\n<p>「小光點」於是誕生。那些點綴在畫面中的細小亮光，象徵著在黑暗中依然存在的希望。它們不張揚、不刺眼、卻持續閃爍。對她而言，那不只是風格，而是一種生命態度——即使經歷挫折，光仍然存在，只是需要時間看見。這樣的創作語言逐漸形成她獨特的辨識度，也慢慢吸引到被觸動的觀者。有人在畫中看見自己的脆弱，有人看見重新站起來的勇氣。她的作品因此不只是畫，而是一種溫柔的陪伴。</p>\n<h3>創業不是衝動，而是一次次理性的選擇</h3>\n<p>提到創業，她的語氣並不激情。她曾為了因應客戶開立收據與發票的需求而成立工作室，也仔細評估營運成本與稅務負擔。當數字與現實擺在眼前時，她選擇暫停下來，而不是硬撐。</p>\n<p>「有時候放下，也是負責任的決定。」</p>\n<p>她坦言，創業不只是創作能力的延伸，更是財務、風險與心理承擔的總和。當身體狀況不允許自己承受過高壓力時，她選擇暫進入公司任職，重新調整節奏。後來再次因健康因素暫停工作，轉而投入繪畫與畫廊合作。</p>\n<p>這些轉折並非失敗，而是理解自己後的選擇。她逐漸明白，比起規模與名聲，更重要的是能否長期、穩定地創作。如今，她以近乎半退休的狀態持續創作，把更多時間留給繪畫與展覽規劃，也讓生活回到一種平衡。</p>\n<h3>用畫筆說話，讓光被看見</h3>\n<p>透過畫廊與藝術空間的合作，她的作品開始被更多人看見。觀者常形容她的畫「很安靜」，但那份安靜裡藏著堅韌。柔和的色調、細緻的筆觸、低調閃爍的光點，構成一種不張揚卻深刻的力量。</p>\n<p>她並不刻意營造戲劇性，也不強調自己曾經歷多少艱難。她只是誠實地畫下當下的心境。或許正因如此，那些畫面才格外真實。未來三年，她沒有設定營收目標，也沒有急著擴大規模。她的回答很簡單：「有靈感就創作。」那是一種從焦慮中走出來後的從容。當創作不再只是職業，而成為生活本身，目標反而變得純粹。</p>\n<h3>給學弟妹的一句話：先準備、再出發</h3>\n<p>談到對年輕創作者的建議，她溫氣淡然：「不要貿然創業。」</p>\n<p>她提醒，創業的風險遠比想像中高。務必要先規劃、先累積經驗、職場雖然辛苦，但能學習到完整流程、專業分工與溝通模式，這些都是日後創業的養分。創業不該是逃離公司，而應該是在理解市場之後的選擇。堅持理想並不等於固執，而是在吸收他人意見的同時，保留自己的核心價值。心態健康，比一時的成功更重要。</p>\n<h3>從黑暗到微光</h3>\n<p>從低谷到創作，從設計到繪畫，鄭佩淳用自己的故事證明——生命的價值不在於是否一帆風順，而在於在黑暗中是否願意替自己點起一道光。那道光或許微小，卻真實存在。而她，正在用畫筆，讓那份光慢慢擴散。</p>', '2025-01-01 00:00:04')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), date = VALUES(date), location = VALUES(location), cover = VALUES(cover), content = VALUES(content), created_at = VALUES(created_at);
INSERT INTO articles (slug, title, description, date, location, cover, content, created_at) VALUES ('ALUM-A006', '【三刀人形創作】在三刀之間，雕出屬於自己的創作人生 邱俊彥：跨界玩家創業故事——桃園專訪', '本文專訪三刀人形創作工作室邱俊彥，分享他從歌仔戲到工業設計，再到雕塑創業的跨界玩家創業故事。', '04 08 2025', '校友特稿', NULL, '<h3>專訪｜邱俊彥：創作，是一種好玩的實驗 雕出自己的創作宇宙 HAVE FUN！</h3>\n<p>目前，邱俊彥身兼三種角色——雕塑家／食品造型藝術家、課程講師，以及創意商品內容創作者。他經營「三刀人形創作」雕塑工作室，在實體創作與教學推廣之間來回切換。</p>\n<p>在他看來，這些身份並非分裂，而是互相延伸。雕塑調練技術深度，教學整理系統邏輯，內容創作則鍛鍊表達能力。他的終圍繞著一個核心信念——Have Fun。</p>\n<p>創作若失去樂趣，就失去靈魂。</p>\n<p>「有時候我甚至覺得，表述與自我行銷能力跟自身能力一樣重要。」</p>\n<p>設計訓練要求學生不只做出模型，還必須清楚說明設計理念與解決方案。這種訓練讓他後來在創業過程中，能夠更有效與客戶溝通，也能把創作理念轉換成市場可以理解的語言。他也提到，在設計史課堂上的一次經驗，讓他意識到自己的觀察力。</p>\n<h3>從歌仔戲到工業設計：選擇挑戰而非簡單</h3>\n<p>談起為何選擇工業設計，他的答案出乎意料。他的創作起點，其實來自童年的興趣——歌仔戲。戲曲人物的臉譜、服裝、神情，深深吸引著他。他開始想：「如果可以親手把這些角色雕塑出來，會是什麼樣子？」</p>\n<p>在升學選擇時，最直覺的方向似乎是工藝相關科系，但他最後卻選擇了工業設計。原因很單純——他喜歡挑戰。</p>\n<p>「工藝比較天馬行空，但我喜歡有現實限制的挑戰。」</p>\n<p>工業設計必須考慮材料、成本、製造方式、市場接受度等多重因素，不只是做出好看的作品，而是在條件限制中找到解法。對他來說，這樣的難度反而更有吸引力。這個選擇，讓他的創作底子不只是感性，也帶著結構與邏輯。</p>\n<p>他認為，工藝創作相對自由奔放，而工業設計需要在現實條件中解決問題，考量成本、結構、量產與市場需求。那種「在限制中完成創意」的過程，對他來說更具吸引力。工業設計的訓練，讓他學會在理想與現實之間取得平衡。</p>\n<h3>設計教育的影響：能力比技術更重要</h3>\n<p>回顧大學時期，他認為工業設計帶給他的最大收穫，不是某一項專業技能，而是三種核心能力的建立：表述能力、動手能力、邏輯與問題解決能力。</p>\n<h3>創業是一種志業：把興趣變成長期投入</h3>\n<p>對邱俊彥而言，創業並非單純的職涯選項，而是一種志業的選擇。出社會後，他持續精進人像雕刻技術，甚至學習佛像雕刻等高難度工法，讓立體結構與比例掌握更為扎實。在長時間磨練中，他逐漸發現，自己的能力已經具備市場競爭力。</p>\n<p>當技術與自信同步成長，他下定決心創業。不是因為討厭體制，而是因為想用自己的方式解決問題，用雕塑語言創造價值。</p>\n<p>創業初期最大的困難，是沒有客源。沒有名氣、沒有曝光，只能從身邊機會開始慢慢累積。但隨著第一批客戶出現，只要作品品質穩定，口碑便會慢慢擴散。客人介紹客人，回頭客逐漸增加，收入才慢慢趨於穩定。這種成長並非爆發式，而是堆積式。他形容，那是一種慢慢發酵的過程。</p>\n<h3>特別的職場經驗談與紙紮的啟示</h3>\n<p>在創業前，他曾在平面設計公司工作，也進入一間專門製作往生者紙紮用品的公司。從紙紮車子、紙紮房子，到各種客製化用品，這些看似特殊的設計工作，讓他理解設計其實承載著情感與儀式意義。</p>\n<p>「那是一種替念做設計。」這段經歷讓他更加理解，設計並非只服務商業，而是服務人心。</p>\n<p>在與客戶意見不合時，他不直接否定，而是提供三個方向。其中一個是他最認同的方案，其餘兩個則相對保守或不那麼突兀。這樣既讓客戶保有選擇權，也自然引導對方靠近理想解。</p>\n<p>同時，他會用專業分析說明不同選項的優缺點，而不是單純主觀判斷。這種溝通方式，既保留創作者立場，也維持合作關係。</p>\n<h3>給年輕設計師的建議：先活下來，再談夢想</h3>\n<p>他給想創業的年輕設計師的建議很實際：第一步是活下來。衡量自己的財務能力，用小成本開始。行銷能力與設計能力同樣重要。</p>\n<p>創作領域難免比較。當看到同行熟人發展更快、技術更成熟時，他也曾動搖，甚至懷疑自己是否適合這條路。但最終，他回到初心——如果還喜歡，那就繼續。</p>\n<p>他學會不再用別人的速度衡量自己，而是專注於自身的進步，不要讓壓力消耗熱情。「太緊繃，很容易把原本喜歡的事情變成負擔。」創業不是一次成功，而是長期調整。</p>\n<h3>未來三年的願景：讓創作走得更遠</h3>\n<p>談到未來，他已有清楚方向。他計畫與出版社合作出書，整理創作經驗與技法；以影音形式記錄創作過程，讓更多人理解手作的價值；開設線上課程，教授手作能力與創意思維。他也希望不只是做作品，而是分享方法。「如果有人因為我的課程而開始創作，那，很有意義。」</p>', '2025-01-01 00:00:05')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), date = VALUES(date), location = VALUES(location), cover = VALUES(cover), content = VALUES(content), created_at = VALUES(created_at);
INSERT INTO articles (slug, title, description, date, location, cover, content, created_at) VALUES ('ALUM-A007', '【北國映像】在影像前端描繪世界觀，呂奇駿:從遊戲美術到電影分鏡的創作——公司專訪', '本文專訪北國映像呂奇駿，分享他從遊戲美術轉向電影分鏡設計，在影像前端描繪世界觀的創作歷程。', '04 08 2025', '校友特稿', NULL, '<h3>專訪｜呂奇駿：在分鏡與文化之間，為台灣日常尋找新的敘事可能與畫面語言</h3>\n<p>在電影正式開拍之前，畫面其實早已誕生。分鏡設計師透過一張張草圖與概念圖，為故事搭建視覺骨架，替導演與劇組確立敘事節奏與畫面語言。呂奇駿，正是站在這個影像前端位置的創作者。</p>\n<p>30歲之前，他在遊戲公司擔任美術相關工作，參與世界觀與畫面風格的建立；30歲之後，他將職涯重心轉向電影與廣告產業，投入分鏡設計與前期概念發想，負責美術方向設定，並協助後期特效團隊理解畫面結構與視覺邏輯。</p>\n<p>對他而言，分鏡不是單純「畫畫」，而是替整部作品建立可被執行的影像藍圖。</p>\n<h3>從日本神話改編，看見台灣文化的可能</h3>\n<p>談及創作理念，呂奇駿特別提到日本影視作品如何重新詮釋傳統神話與文化元素。像《火影忍者》將忍者文化轉化為當代少年成長敘事，《咒術迴戰》則將咒術與宗教元素重構為完整的戰鬥體系。這些作品並非單純借用傳統，而是透過再創造，讓文化在現代語境中重生。</p>\n<p>他認為，台灣同樣具備轉化文化的潛力。「我們的日常就是文化。」</p>\n<p>在他眼中，下班時間柵欄內停滿機車的景象、城市巷弄的鐵皮屋、街邊宮廟的燈光與煙霧，都是屬於台灣的視覺符號。關鍵不在於是否擁有宏大的神話，而在於是否願意重新觀看生活，並將其轉化為影像語言。這種對日常的敏感觀察，也成為他創作的重要養分。</p>\n<h3>一次志願選擇，走入工業設計訓練</h3>\n<p>回顧求學歷程，他坦言選擇工業設計並非源於遠大志向。當時分數落點符合，加上本身喜歡畫圖，又認為工業設計具有企業資源與延展性，於是踏入這個領域。</p>\n<p>然而真正改變他視野的，是大學期間的一門表現技法課。在田瑜老師的課堂上，他接觸到《星際大戰》畫冊，第一次意識到表現技法不僅能用於產品渲染，更可以建構前衛世界觀與敘事空間。那一刻，他理解設計並不只是面對企業上班族的道路，也能延伸至影像與概念創作領域。</p>\n<p>此外，在JL實習期間，他曾因建模能力不足而感到挫折，但在上司指導下補強透視與3D建模技巧。這些基礎能力，後來成為他投入電影分鏡與概念設計的重要支撐。工業設計訓練帶給他的，不只是技術，更是邏輯建構與視覺轉譯能力——如何把抽象想法具體化，如何讓他人看懂並願意執行。</p>\n<h3>創業的起點：從請款需求到品牌意識</h3>\n<p>談到創業契機，呂奇駿的回答相當務實。最初成立公司，只是因為專案需要開立發票才能順利請款。然而隨著接案量增加，他逐漸意識到，若要在影像產業中站穩腳步，不能僅依賴單一專案，而必須在行銷與品牌建立上提前布局。</p>\n<p>創業初期最大的挑戰，是如何打開知名度。影像產業高度依賴信任與口碑，沒有代表作品背書時，每一次提案都格外艱難。他也坦言，若一畢業便創業，將承受更大的壓力。過去在遊戲公司工作的經驗與人脈，為後來的發展奠定基礎。</p>\n<p>至於是否曾想放棄，他沒有給出戲劇化答案，只表示近期確實感到低潮與沮喪。創作與市場並行的壓力，使情緒波動成為常態，但也讓他更清楚自己仍想持續走在這條路上。</p>\n<h3>分鏡設計：在理解中對齊方向</h3>\n<p>在與導演或客戶溝通時，他強調第一件事是確認自己的定位。分鏡設計師的角色，不是主導創作，而是理解導演真正想要的畫面語言，並將其轉化為可執行的視覺方案。</p>\n<p>若導演已有明確方向，他負責精準呈現；若對方尚未形成清晰想法，他則會提供多組草圖與視覺參考，透過「選擇題」方式協助對方聚焦。這些草圖本身就是溝通工具。當雙方對畫面方向達成共識，後續創作才會更有效率。</p>\n<p>在他看來，分鏡是一種翻譯工作——在不同創作角色之間建立共同語言。</p>\n<h3>未來三年：完成屬於自己的創作</h3>\n<p>2023年，當井上雄彥將《灌籃高手》改編為電影上映時，呂奇駿深受觸動。看到同世代創作者將漫畫世界搬上大銀幕，他為此立下新的目標。</p>\n<p>目前他仍多為電影專案提供設計服務，但未來三年，他希望在保持身體健康的前提下，投入屬於自己的創作計畫。成功與否並非最重要的衡量標準。更重要的是，他想證明自己曾真正嘗試。</p>\n<p>在替他人描繪畫面的同時，他也正為自己的人生故事，慢慢構築分鏡。</p>', '2025-01-01 00:00:06')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), date = VALUES(date), location = VALUES(location), cover = VALUES(cover), content = VALUES(content), created_at = VALUES(created_at);
INSERT INTO articles (slug, title, description, date, location, cover, content, created_at) VALUES ('ALUM-A008', '【星芮插畫】以筆觸打造個人品牌 王敬涵:用插畫描繪生活與想像——工作室專訪', '本文專訪星芮插畫創辦人王敬涵，分享她從插畫創作到品牌經營，探索創作與教育的多重可能。', '04 08 2025', '校友特稿', NULL, '<h3>專訪｜王敬涵：從插畫創作到品牌經營，探索創作與教育的多重可能</h3>\n<p>王敬涵，目前是插畫創作者與創業者，經營個人插畫品牌「星芮插畫」。在品牌中，她同時擔任創作者與負責人，掌握整體創作方向、專案規劃與對外合作溝通。從平面設計、品牌視覺到網站設計、動畫製作，再到展覽策展與社群視覺規劃，星芮插畫的業務範疇涵蓋廣泛。</p>\n<p>早期，她幾乎「什麼案子都接」，為了累積經驗與維持收入；而隨著品牌逐漸成長，她開始篩選合作對象，帶領兩位團隊成員以彈性責任制完成各項專案，逐步建立起自我風格與品牌定位。</p>\n<h3>誤打誤撞的工業設計起點</h3>\n<p>王敬涵回憶，大學填志願時，她原本就讀三類組，本可選擇醫學或生命科學相關科系，但考慮到未來是否願意長時間待在實驗室，她選擇了一條偏向創意與互動性的路——工業設計。對她而言，這是一個「誤打誤撞」的選擇，但也正是這次選擇，為她後續的創作與創業奠定了重要基礎。</p>\n<p>她表示，大學學習最寶貴的，不是技法，而是「思考與探索方向的能力」。在教授的指導下，她參與國科會計畫、撰寫論文、技術研究，並前往日本與亞洲設計論壇發表作品。這些經歷讓她學會如何自主研究、獨立思考，並將想法以系統化呈現。這份能力也直接影響她日後在創業中整合各類設計專案與品牌塑的能力。</p>\n<p>在大學期間，王敬涵特別提到指導教授對她的影響。教授不以誇獎為導向，而是鼓勵學生深入思考問題、探索解決方法。她在國科會研究計畫與海外發表的經驗，也讓她在大三大四時開始明確思考自己未來真正想走的道路。她說：「當時我才理解，設計不只是畫漂亮的圖，而是一種能解決問題、表達觀點的工具。」</p>\n<h3>創業契機與初期挑戰</h3>\n<p>踏上創業之路的契機，其實源於最直接的需求：為了接案，她需要開立發票、報價單與正式合約，因此成立公司。然而，隨著時間推進，她逐漸將目標擴展至打造長期累積的個人品牌，而非僅替他人公司完成作品。</p>\n<p>創業初期，最大的挑戰來自於品牌知名度與客戶累積。王敬涵坦言，一開始除了要兼顧創作，還需要處理行政事務如開發票、合約、報價等，對一個創作者而言，既繁瑣又耗心力。</p>\n<p>尤其身為母親，她會在深夜仍需處理工作，同時照顧孩子，曾多次懷疑自己是否應該回到穩定上班族生活，但最終選擇堅持創業，「那時我告訴自己，如果放棄，永遠不會知道自己能走多遠。」</p>\n<h3>代表性合作與成就感</h3>\n<p>在多年的創業與創作經驗中，王敬涵累積了許多值得回憶的專案。她曾為遊艇公司設計整體品牌視覺與網站，這個專案為她帶來後續大量相關合作，也奠定了品牌在高端市場的聲譽。</p>\n<p>近期，她策劃的「365 天微客製化設計」企劃案在社群上獲得近兩千人按讚與大量分享，讓她感受到創作與觀眾互動的直接回饋。除此之外，她也曾與大型上市公司合作動畫專案，雖然過程辛苦，但她視其為重要代表作，「每一次合作都不只是作品呈現，更是一種學習和自我挑戰。」面對客戶意見不合或修改要求，王敬涵認為溝通至關重要。</p>\n<p>她會先了解客戶需求，若客戶沒有明確方向，會提供多個選項，並透過草圖或資料說明引導，確保雙方達成共識。她也強調「該有的底線要堅持」，避免無止盡的修改。過去，她會因合作理念不合而拆夥，並學會選擇適合的合作對象，這也是她品牌成熟的重要一課。</p>\n<h3>對年輕創作者的建議</h3>\n<p>對於想創業的年輕設計師，王敬涵給出了明確建議：「創立個人品牌非常重要，要找到自己的風格。」她認為創業初期最重要的是清楚知道自己喜歡做什麼，而不是迎合所有客戶。</p>\n<p>「一定要以自己的喜好篩選客戶，而不是讓客戶篩選你。」</p>\n<p>建立明確風格與方向，是長期累積品牌影響力的核心。</p>', '2025-01-01 00:00:07')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), date = VALUES(date), location = VALUES(location), cover = VALUES(cover), content = VALUES(content), created_at = VALUES(created_at);

